 bool Save(){businessSaves++;if(failSave)return false;Directory.CreateDirectory(DataDirectory);if(!File.Exists(SaveFile))File.WriteAllText(SaveFile,"; owner comment\r\n[Business]\r\nCash=1234\r\nParts=0\r\n[Unknown]\r\nKeep=untouched\r\n[Storage]\r\nOwnedPallets=4\r\nDeliveredPackageMask1=7\r\n[MechanicProfile1]\r\nJobOutboundMask=17\r\nJobReturnMask=6\r\n");var c=new PlacementChange{Points=PlacementScope(6),IncludeAnchor=true,ShopPlaced=_placed,Location=_location,Equipment=true,Office=_officeDeskPlaced,Tools=_toolSetPlaced,Scanner=_scannerPlaced};foreach(var p in c.Points){p.Set=p.Target.IsSet;p.Position=p.Target.Position;p.Heading=p.Target.Heading;}File.WriteAllBytes(SaveFile,EncodePlacementPatch(File.ReadAllBytes(SaveFile),PlacementOverrides(c)));afterSave?.Invoke();return true;}
