 static Harness Ready(){var h=new Harness{_menuPage=MenuPage.PlacementReset};Directory.CreateDirectory(FixtureRoot);File.WriteAllText(h.PlacementInstalledSource(),"synthetic source only");Directory.CreateDirectory(DataDirectory);File.WriteAllText(SettingsFile,"; user settings\n[Unknown]\nPreserve=yes\n");File.WriteAllText(Path.Combine(DataDirectory,"CustomerOrders.csv"),"id,amount\n1,99\n");foreach(var p in h.PlacementVisuals()){p.Point.IsSet=true;p.Point.Position=new Vector3(10,20,30);p.Point.Heading=90;}h._mechanics[0].SavedPost.IsSet=h._receptionist.SavedPost.IsSet=true;h.Save();h.businessSaves=0;return h;}
 static string Backup(Harness h)=>CreatePlacementBackup(DataDirectory,h.PlacementInstalledSource(),h.PlacementBackupRoot(),(a,b)=>File.Copy(a,b,false));
 static bool Throws(Action a){try{a();return false;}catch{return true;}}
 static Dictionary<string,string> One(string section,string key,string value)=>new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){{section+"\0"+key,value}};
 static void FinalYes(Harness h,int group,bool restore=false){h.StartPlacementRequest(group,restore,0);Check(h._placementRequest!=null,"request blocked: "+string.Join(";",h.notices));h._selection=1;h.ExecutePlacementResetSelection();Check(h._menuPage==MenuPage.PlacementResetConfirm&&h._selection==0,"second default NO");h._selection=1;h.ExecutePlacementResetSelection();}
 static void Main(){
 Test("lifecycle rejects boot, pause, open/remote, customer, queued and promise obligations",()=>{Action<Harness>[] block={h=>h._bootGameplayActivated=false,h=>Game.IsPaused=true,h=>h._clockedIn=true,h=>h._remoteMode=true,h=>h._activeCustomerOrders.Add(new object()),h=>h._customerOrder=new object(),h=>h._stagedCustomerOrder=new object(),h=>h._stagedThirdCustomerOrder=new object(),h=>h._waitingCustomerRequests=1,h=>h._remoteJobs.Add(new object()),h=>h._pendingRepairPromises.Add(new object()),h=>h._mechanics[0].HasJob=true};foreach(var change in block){Game.IsPaused=false;var h=new Harness();change(h);Check(h.PlacementOperationBlock()!=null,"unsafe allowed");}Game.IsPaused=false;});
 Test("lifecycle rejects every pending delivery/cargo/owned shipment actor",()=>{Action<Harness>[] block={h=>h._deliveryKind=0,h=>h._supplierPlayerCarrying=true,h=>h._wholesaleCargoLoaded=true,h=>h._wholesaleCargoUnloaded=true,h=>h._supplierTruck=new Vehicle(),h=>h._supplierDriver=new Ped(),h=>h._supplierCrate=new Prop()};foreach(var change in block){var h=new Harness();change(h);Check(h.PlacementOperationBlock()!=null,"shipment allowed");}});
 Test("safe lifecycle is eligible and busy owner distinction is bounded",()=>{var h=new Harness();Check(h.PlacementOperationBlock()==null,"safe blocked");h._placementTransactionActive=true;Check(h.PlacementOperationBlock()!=null&&h.PlacementOperationBlock(true)==null,"busy guard");});
 Test("all category scopes exclude ledger, masks and fixed world warehouse",()=>{var h=Ready();for(int g=0;g<7;g++){var keys=PlacementOverrides(h.BuildPlacementChange(g,false,null));Check(!keys.Keys.Any(k=>k.StartsWith("Business\0")||k.Contains("JobOutboundMask")||k.Contains("DeliveredPackageMask")||k.StartsWith("SupplierWarehousePickup\0")||k.StartsWith("Storage\0")),"whitelist");}Check(h.PlacementScope(1).Any(p=>p.Section=="MechanicResumePost1")&&h.PlacementScope(3).Any(p=>p.Section=="ReceptionistResumePost"),"stale resume");});
 Test("individual customer reset preserves every other coordinate",()=>{var h=Ready();var c=h.BuildPlacementChange(0,false,null);h.ApplyPlacementChange(c);Check(!h._customerDropoff.IsSet&&h._bays[0].IsSet&&h._supplierPartsPallet.IsSet&&h._placed,"category spill");});
 Test("shop anchor is opt-in only for full scope",()=>{var h=Ready();Check(!h.BuildPlacementChange(0,true,null).IncludeAnchor&&!h.BuildPlacementChange(6,false,null).IncludeAnchor&&h.BuildPlacementChange(6,true,null).IncludeAnchor,"anchor scope");});
 Test("geometry patch preserves literal unrelated keys comments and CRLF",()=>{string text="; Keep comment\r\n[Business]\r\nCash = 777\r\n[CustomerDropoff]\r\nSet=True\r\nX=10\r\nUnknown=keep\r\n";string result=PatchPlacementIni(text,One("CustomerDropoff","X","0"));Check(result==text.Replace("X=10","X=0"),"unrelated text rewritten");});
 Test("missing spatial keys append to proper existing or new sections",()=>{string result=PatchPlacementIni("[Unknown]\nKeep=yes",new Dictionary<string,string>{{"Unknown\0New","value"},{"NewPoint\0Set","False"}});var values=ReadPlacementIni(result);Check(values["Unknown\0Keep"]=="yes"&&values["Unknown\0New"]=="value"&&values["NewPoint\0Set"]=="False","new sections");});
 Test("UTF8 BOM and both UTF16 encodings are preserved",()=>{foreach(var encoding in new System.Text.Encoding[]{new System.Text.UTF8Encoding(true),new System.Text.UnicodeEncoding(false,true),new System.Text.UnicodeEncoding(true,true)}){byte[] bom=encoding.GetPreamble();byte[] original=bom.Concat(encoding.GetBytes("[Point]\r\nX=1\r\n[Unknown]\r\nValue=\u00e9\r\n")).ToArray();byte[] result=EncodePlacementPatch(original,One("Point","X","2"));Check(result.Take(bom.Length).SequenceEqual(bom)&&encoding.GetString(result,bom.Length,result.Length-bom.Length).Contains("Value=\u00e9\r\n"),"encoding lost");}});
 Test("duplicate keys and malformed text fail closed",()=>{Check(Throws(()=>EncodePlacementPatch(System.Text.Encoding.UTF8.GetBytes("[P]\nX=1\nX=2\n"),One("P","X","0"))),"duplicate allowed");Check(Throws(()=>ReadPlacementIni("[broken\nX=1\n")),"malformed section");});
 Test("complete backup includes source Settings CSV and verified checksums",()=>{var h=Ready();string b=Backup(h);VerifyPlacementBackup(h.PlacementBackupRoot(),b);Check(File.Exists(Path.Combine(b,"Source.cs.txt"))&&File.ReadAllText(Path.Combine(b,"Data","Settings.ini"))==File.ReadAllText(SettingsFile)&&File.ReadAllText(Path.Combine(b,"Data","CustomerOrders.csv"))==File.ReadAllText(Path.Combine(DataDirectory,"CustomerOrders.csv")),"incomplete backup");});
