 Test("placement restore keeps current cash masks and stock rather than old backup ledger",()=>{var h=Ready();FinalYes(h,0);string oldBackup=h._lastPlacementBackup;File.WriteAllText(SaveFile,File.ReadAllText(SaveFile).Replace("Cash=1234","Cash=9999"));h._lastPlacementBackup=oldBackup;FinalYes(h,0,true);var saved=ReadPlacementIni(File.ReadAllText(SaveFile));Check(h._customerDropoff.IsSet&&h._customerDropoff.Position.X==10&&saved["Business\0Cash"]=="9999"&&saved["MechanicProfile1\0JobReturnMask"]=="6"&&h._lastPlacementBackup!=oldBackup,"restore old ledger");});
 Test("restore cannot enable unowned equipment",()=>{var h=Ready();string b=Backup(h);h._officeDeskPurchased=false;var c=h.BuildPlacementChange(5,false,Path.Combine(b,"Data","Save.ini"));Check(!c.Office&&!h._officeDeskPurchased&&c.Points.Single(p=>p.Section=="OfficeDesk").Set,"ownership changed");});
