 Test("geometry and restore helpers preserve unrelated unknown text",()=>{var h=Ready();string old=File.ReadAllText(SaveFile);FinalYes(h,2);Check(File.ReadAllText(SaveFile).Contains("; owner comment\r\n")&&File.ReadAllText(SaveFile).Contains("[Unknown]\r\nKeep=untouched\r\n")&&h._bays[0].IsSet,"unknown values");});
 Test("no backup exists before an explicitly confirmed action",()=>{var h=Ready();h.StartPlacementRequest(0,false,0);h.PlacementRequestDescription();Check(!Directory.Exists(h.PlacementBackupRoot())&&h.businessSaves==0,"review wrote backup/save");});
 Test("commit rejects a request before its explicit first YES",()=>{var h=Ready();h.StartPlacementRequest(0,false,0);Check(!h.CommitPlacementRequest()&&h.businessSaves==0&&h._customerDropoff.IsSet,"stage bypass");});
